// Check the loaded build and run code once the DOM is parsed
console.log($.fn.jquery); // "3.7.1"

$(function () {
  $("#app").addClass("ready");
});

// ID, class and tag lookups
$("#sidebar");
$(".card");
$("li");

// CSS combinators behave as they do in stylesheets
$("nav > ul li.active");
$("h2 + p");

// Attribute selectors
$('a[href^="https://"]');
$('input[type="email"]');
$('img[alt!="logo"]');

// Positional filters are jQuery extensions, not CSS
$("li:first");
$("li:last");
$("li:eq(2)");   // zero-based, so the third item
$("li:even");
$("li:gt(3)");

// State filters
$("input:checked");
$("div:visible");
$("div:hidden");

// A selector can be a string, a DOM node, or an existing set
const hero = document.querySelector("#hero");
$(hero).addClass("seen");

// The second argument scopes the search to a context
$("button", "#toolbar");

// Cache a set and reuse it instead of querying again
const $rows = $(".row");
$rows.filter(".selected").css("font-weight", "bold");

$(function () {
  // Direct binding
  $("#save").on("click", function (event) {
    event.preventDefault();
    console.log("saved");
  });

  // Delegation also covers rows created later
  $("#todo-list").on("click", "li", function () {
    $(this).toggleClass("done");
  });
});

// Namespaced handlers are removed together
$("#panel").on("mouseenter.tip", showTip);
$("#panel").on("mouseleave.tip", hideTip);
$("#panel").off(".tip");

// Fire once, then detach
$("#welcome").one("click", function () {
  $(this).fadeOut();
});

// Custom events bubble like native ones and can carry data
$("#cart").on("cart:updated", function (event, count) {
  console.log("items", count);
});
$("#cart").trigger("cart:updated", [3]);

// event.target is the clicked node, this is the bound element
$("#menu").on("click", "a", function (event) {
  if ($(event.target).is("span")) return; // ignore the badge inside the link
  event.stopPropagation();
});

// Durations accept milliseconds or the keywords "fast" and "slow"
$("#panel").hide();
$("#panel").show(200);
$("#panel").toggle("fast");

// Named effects
$("#notice").fadeIn(300);
$("#notice").fadeOut(300);
$("#notice").fadeToggle(300);
$("#menu").slideDown(250);
$("#menu").slideUp(250);
$("#menu").slideToggle(250);

// animate() only interpolates numeric properties
$("#box").animate(
  { left: "+=80px", opacity: 0.5 },
  600,
  "swing",
  function () {
    $(this).addClass("moved");
  }
);

// Queue control
$("#box").stop(true, true); // clear the queue and jump to the end
$("#box").finish();         // stop and complete every queued effect
$("#box").delay(200).fadeIn(200);

// text() escapes, html() parses markup
const title = $("#title").text();
$("#title").text("New title");
$("#summary").html("<strong>Bold</strong> summary");

// Empty a container before refilling it
$("#log").empty();
$("#log").append("<p>first line</p>");

// Build an element with attributes in one call
const $item = $("<li>", {
  class: "entry",
  text: "Ship it",
  "data-id": 42
});
$("#list").append($item);

// Insert relative to existing nodes
$item.prependTo("#list");
$item.insertAfter("#list li:first");
$item.before("<li>before</li>");

// remove() drops data and handlers, detach() keeps them for reuse
const $row = $("#row-7").detach();
$("#archive").append($row);

$("#row-8").remove();

// Swap an element for new markup, or wrap it in a container
$("#old").replaceWith('<div id="new">fresh</div>');
$("#new").wrap('<section class="frame"></section>');

$("#tab").addClass("active");
$("#tab").removeClass("active");
$("#tab").toggleClass("active");

// The second argument forces the result
$("#tab").toggleClass("active", isOpen);
$("#tab").addClass("a b c");

// Test before acting
if ($("#tab").hasClass("active")) {
  console.log("selected");
}

// attr() handles HTML attributes
const href = $("#link").attr("href");
$("#link").attr("target", "_blank");
$("#link").removeAttr("target");

// prop() handles live state such as checked and disabled
$("#agree").prop("checked", true);
$("#agree").prop("disabled", false);

$.ajax({
  url: "/api/issues",
  method: "GET",
  data: { state: "open", page: 2 },
  dataType: "json"
})
  .done(function (issues) {
    console.log(issues.length, "issues");
  })
  .fail(function (xhr, status, error) {
    console.error(status, error, xhr.status);
  })
  .always(function () {
    $("#spinner").hide();
  });

// POST JSON: set the content type and stringify the body
$.ajax({
  url: "/api/issues",
  method: "POST",
  contentType: "application/json",
  data: JSON.stringify({ title: "Login fails", priority: "high" })
}).done(function (created) {
  $("#list").append($("<li>").text(created.title));
});

// Shorthand for GET plus JSON parsing
$.getJSON("/api/users/7", function (user) {
  $("#name").text(user.name);
});

// Wait for two requests to finish
$.when($.getJSON("/api/user"), $.getJSON("/api/team")).done(
  function (userRes, teamRes) {
    console.log(userRes[0].name, teamRes[0].length);
  }
);

// Per-request timeout and headers
$.ajax({
  url: "/api/health",
  timeout: 5000,
  headers: { "X-Client": "cheatrs" }
});

const $card = $(".card.selected");

$card.find(".title");       // all descendants
$card.children("a");        // direct children only
$card.parent();             // immediate parent
$card.closest(".card");     // nearest matching ancestor
$card.siblings(".card");    // peers, not counting itself
$card.next();
$card.nextAll("a");

// Narrow a set without touching the document
const $rows = $("#table tr");
$rows.filter(".paid");
$rows.not(".paid");
$rows.has("input:checked");
$rows.eq(0);
$rows.first();
$rows.last();
$rows.slice(2, 5);

// each() iterates; return false stops the loop
$("#list li").each(function (index) {
  $(this).prepend(index + 1 + ". ");
});

// map() collects a plain array
const labels = $("#list li")
  .map(function () {
    return $(this).text();
  })
  .get();

// end() returns to the previous set in the chain
$("#list").find("li").addClass("row").end().addClass("has-rows");

// serialize() produces a URL-encoded string for classic posts
$("#signup").on("submit", function (event) {
  event.preventDefault();
  const payload = $(this).serialize();

  $.post("/signup", payload).done(function () {
    $("#signup")[0].reset();
  });
});

// serializeArray() keeps names and values as objects
const fields = $("#signup").serializeArray();
// [{ name: "email", value: "ana@example.com" }, ...]

// Read and write single controls
const email = $("#email").val();
$("#email").val("ana@example.com");

// Checkboxes and radios use prop, not attr
$('input[name="plan"]:checked').val();
$("#terms").prop("checked", true);

// Trigger a handler from code
$("#signup").trigger("submit");

// Check before sending and mark the field
$("#signup").on("submit", function (event) {
  const email = $("#email").val().trim();

  if (!email.includes("@")) {
    event.preventDefault();
    $("#email").addClass("invalid").trigger("focus");
  }
});

// A plugin is a function on $.fn; return this to stay chainable
$.fn.highlight = function (options) {
  const settings = $.extend({ color: "#fff3a3" }, options);

  return this.each(function () {
    $(this).css("background-color", settings.color);
  });
};

$("p.note").highlight({ color: "#d1f7c4" });

// Keep per-element state in data(), never in globals
$.fn.counter = function (step) {
  const increment = step || 1;

  return this.each(function () {
    const $el = $(this);
    const value = ($el.data("count") || 0) + increment;
    $el.data("count", value).text(value);
  });
};

$(".badge").counter(2);

// Namespace events so off() removes only your own handlers
$.fn.dismissible = function () {
  return this.each(function () {
    $(this).on("click.dismissible", ".close", function () {
      $(this).closest(".alert").slideUp();
    });
  });
};

$(".alert").dismissible();

// Instead of $(selector)
const el = document.querySelector("#app");
const items = document.querySelectorAll(".item");

// Instead of addClass / removeClass / toggleClass
el.classList.add("ready");
el.classList.remove("ready");
el.classList.toggle("open", isOpen);

// Instead of text() and html()
el.textContent = "Done";
el.innerHTML = "<strong>Done</strong>";

// Instead of $.ajax, wrapped so the await stays inside a function
async function loadIssues() {
  const res = await fetch("/api/issues", {
    headers: { Accept: "application/json" }
  });
  if (!res.ok) throw new Error(res.status);
  return res.json();
}

// Instead of a POST with a serialized body
fetch("/api/issues", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ title: "Login fails" })
});

// Instead of delegated .on("click", "li", ...)
document.querySelector("#list").addEventListener("click", (event) => {
  const row = event.target.closest("li");
  if (row) row.classList.toggle("done");
});

// Instead of append() and insertAfter()
const list = document.querySelector("#list");
list.append(document.createElement("li"));
list.insertAdjacentHTML("beforeend", "<li>Ship it</li>");
